const data=window.WORKBENCH_DATA;
if(data){const m=data.metrics;const summary=document.querySelectorAll('.summary-grid strong');[m.alertAsins,m.causeRows,m.actionTotal,m.investableAsins].forEach((value,index)=>summary[index].textContent=value.toLocaleString());const rail=document.querySelectorAll('.goal-card strong');[m.alertAsins,m.causeRows,m.investableAsins,m.negativeCandidates].forEach((value,index)=>rail[index].textContent=value.toLocaleString());document.querySelector('.summary-grid article:nth-child(1) small').textContent=`${(m.alertAsins/m.monitoredAsins*100).toFixed(1)}% 进入预警`;document.querySelector('.data-status small').textContent=`最近分析结果：${data.latestResultAt}；工作台同步：${data.refreshedAt}`;}
document.querySelector('#jumpQueue').addEventListener('click',()=>document.querySelector('#queue').scrollIntoView({behavior:'smooth'}));
document.querySelectorAll('.filters button').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.filters button').forEach(x=>x.classList.remove('active'));button.classList.add('active');const current=button.dataset.filter;document.querySelectorAll('.queue-table .tr:not(.th)').forEach(row=>row.hidden=current!=='all'&&row.dataset.priority!==current)}));
let showingPercent=false;document.querySelector('#toggleBars').addEventListener('click',event=>{showingPercent=!showingPercent;const values=showingPercent?['26%','72%','100%','70%']:['154','431','597','419'];document.querySelectorAll('.bar-chart strong').forEach((el,index)=>el.textContent=values[index]);event.currentTarget.textContent=showingPercent?'切换为数量':'切换为占比'});
// 模块工作区统一由 module.html 承担；主页不再按 query 改写为另一套页面。
const selectedModule=null;
const moduleInfo={a:{name:'ASIN 周环比监控',key:'alertAsins',label:'预警 ASIN',scope:'VC1 转向器 ASIN · W35 vs W34',files:[['最终预警明细','../../04_分析结果/模块A_最终预警明细表_2026-W35_vs_2026-W34.xlsx'],['周环比监控表','../../04_分析结果/模块A_ASIN周环比监控表_2026-W35_vs_2026-W34.csv']]},b:{name:'掉量原因归因',key:'causeRows',label:'归因结论',scope:'预警 / 掉量 ASIN · 日粒度 21 天窗口',files:[['掉量起点表','../../04_分析结果/模块B_ASIN掉量起点表.csv'],['下滑原因归因表','../../04_分析结果/模块B_下滑原因归因表.csv']]},c:{name:'活动诊断与重构',key:'campaignActions',label:'活动处置',scope:'广告活动 · 适配冲突与重复投放',files:[['活动处置清单','../../04_分析结果/模块C_活动处置清单_最终.csv'],['重复活动清单','../../04_分析结果/模块C_重复活动清单.csv']]},d:{name:'无效流量与否词校验',key:'negativeCandidates',label:'候选待确认',scope:'搜索词低效消耗治理',files:[['候选否词清单','../../04_分析结果/模块D_否词清单.csv'],['否词校验表','../../04_分析结果/模块E_否词校验表.csv']]},f:{name:'潜力词',key:'opportunities',label:'增长机会',scope:'搜索词报告与关键词库',files:[['潜力词清单','../../04_分析结果/模块F_潜力词清单.csv']]},g:{name:'盈亏平衡 ACOS',key:'investableAsins',label:'可增投 ASIN',scope:'有广告动作的 ASIN · 2026-08 成本',files:[['ASIN 盈亏平衡表','../../04_分析结果/模块G_ASIN盈亏平衡表.csv']]}};
const escapeHtml=value=>String(value??'—').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const displayValue=value=>{const text=String(value??'—');return text.length>38?`${text.slice(0,38)}…`:text};
if(selectedModule&&moduleInfo[selectedModule]){const info=moduleInfo[selectedModule];const result=data?.moduleResults?.[selectedModule]||{headline:'尚未同步本模块分析结果',insights:[],distribution:[],columns:[],rows:[]};const value=(data?.metrics?.[info.key]??0).toLocaleString();document.title=`${info.name} · 转向器工作台`;document.querySelectorAll('.nav-link').forEach(link=>link.classList.toggle('active',link.getAttribute('href')===`module.html?module=${selectedModule}`));const logic=(result.insights||[]).map(item=>`<li>${escapeHtml(item)}</li>`).join('');const distribution=(result.distribution||[]).map(item=>`<div class="mini-stat"><span>${escapeHtml(item.label)}</span><strong>${Number(item.value||0).toLocaleString()}</strong></div>`).join('')||'<small>暂无可汇总的分类结果</small>';const header=(result.columns||[]).map(column=>`<th>${escapeHtml(column[0])}</th>`).join('');const body=(result.rows||[]).map(row=>`<tr>${(result.columns||[]).map(column=>`<td title="${escapeHtml(row[column[1]])}">${escapeHtml(displayValue(row[column[1]]))}</td>`).join('')}</tr>`).join('')||`<tr><td colspan="${Math.max((result.columns||[]).length,1)}">暂无结果，请先运行本模块分析并刷新工作台数据。</td></tr>`;const files=info.files.map(file=>`<a class="result-link" href="${file[1]}">打开${file[0]} ↗</a>`).join('');document.querySelector('.center').innerHTML=`<section class="welcome-row"><div><p class="section-kicker">模块分析 / ${info.scope}</p><h1>${info.name}</h1><p>${escapeHtml(result.headline)}</p></div><a class="main-action" href="dashboard.html">← 返回主页看板</a></section><section class="summary-grid"><article><span>${info.label}</span><strong>${value}</strong><small class="green">已同步分析结果</small></article><article><span>分析范围</span><strong>${(result.rows||[]).length}</strong><small>展示优先级最高的结果明细</small></article><article><span>结果状态</span><strong>待确认</strong><small>建议先核对证据，再执行动作</small></article><article><span>更新时间</span><strong>最新</strong><small>${escapeHtml(data?.refreshedAt||'待同步')}</small></article></section><section class="two-col module-insights"><article class="panel"><div class="panel-title"><div><span class="icon">◎</span><strong>分析判断逻辑</strong><small>用于解释结论，不展示脚本处理路径</small></div></div><ol class="logic-list">${logic}</ol></article><article class="panel"><div class="panel-title"><div><span class="icon">▦</span><strong>当前结论分布</strong><small>来自本模块最新分析结果</small></div></div><div class="mini-stats">${distribution}</div></article></section><section class="panel result-panel"><div class="panel-title"><div><span class="icon">▤</span><strong>重点分析结果</strong><small>仅展示前 6 条；完整结果可在下方文件打开</small></div></div><div class="result-table-wrap"><table class="result-table"><thead><tr>${header}</tr></thead><tbody>${body}</tbody></table></div><div class="result-links">${files}</div></section>`;}
